    "question": "Consider the context-free grammar G below\nS → aSb | X\nX → aX | Xb | a | b ,\nwhere S and X are non-terminals, and a and b are terminal symbols. The starting\nnon-terminal is S.\nWhich one of the following statements is CORRECT?",
