    "id": "gate-2023-cs-q53",
    "question": "Consider functions Function 1 and Function 2 expressed in pseudocode as\nfollows:\nFunction 1\nwhile n > 1 do\nfor i = 1 to n do\nx = x + 1;\nend for\nn = \u0005n/2\u0006;\nend while\nFunction 2\nfor i = 1 to 100 ∗ n do\nx = x + 1;\nend for\nLet f1(n) and f2(n) denote the number of times the statement “x = x + 1” is\nexecuted in Function 1 and Function 2, respectively.\nWhich of the following statements is/are TRUE?",
