    "id": "gate-2023-cs-q54",
    "question": "Let G be a simple, finite, undirected graph with vertex set {v1, . . . , vn}. Let Δ(G)\ndenote the maximum degree of G and let N = {1, 2, . . .} denote the set of all possible\ncolors. Color the vertices of G using the following greedy strategy:\nfor i = 1, . . . , n\ncolor(vi) ← min{j ∈ N : no neighbour of vi is colored j}\nWhich of the following statements is/are TRUE?",
    "questionType": "MSQ",
