    "question": "A computer has two processors, M1 and M2. Four processes P1, P2, P3, P4 with CPU\nbursts of 20, 16, 25, and 10 milliseconds, respectively, arrive at the same time and\nthese are the only processes in the system. The scheduler uses non-preemptive\npriority scheduling, with priorities decided as follows:\n• M1 uses priority of execution for the processes as, P1 > P3 > P2 > P4, i.e.,\nP1 and P4 have highest and lowest priorities, respectively.\n• M2 uses priority of execution for the processes as, P2 > P3 > P4 > P1, i.e.,\nP2 and P1 have highest and lowest priorities, respectively.\nA process Pi is scheduled to a processor Mk, if the processor is free and no other\nprocess Pj is waiting with higher priority. At any given point of time, a process can\nbe allocated to any one of the free processors without violating the execution\npriority rules. Ignore the context switch time. What will be the average waiting time\nof the processes in milliseconds?",
