    "question": "Consider the following four variable Boolean function in sum-of-product form\nF(b3, b2, b1, b0) = ∑(0, 2, 4, 8, 10, 11, 12).\nwhere the value of the function is computed by considering b3b2b1b0 as a 4-bit\nbinary number, where b3 denotes the most significant bit and b0 denotes the least\nsignificant bit. Note that there are no don’t care terms. Which ONE of the following\noptions is the CORRECT minimized Boolean expression for F?",
