    "id": "gate-2025-cs1-q52",
    "question": "Refer to the given 3-address code sequence. This code sequence is split into basic\nblocks. The number of basic blocks is ________. (Answer in integer)\n1001: i = 1\n1002: j = 1\n1003: t1 = 10*i\n1004: t2 = t1+j\n1005: t3 = 8*t2\n1006: t4 = t3-88\n1007: a[t4] = 0.0\n1008: j = j+1\n1009: if j <= 10 goto 1003\n1010: i = i+1\n1011: if i <= 10 goto 1002\n1012: i = 1\n1013: t5 = i-1\n1014: t6 = 88*t5\n1015: a[t6] = 1.0\n1016: i = i+1\n1017: if i <= 10 goto 1013\n\nComputer Science and Information Technology (CS1)\nOrganising Institute: IIT Roorkee",
