    "question": "Consider the following C program:\n#include <stdio.h>\nint gate (int n) {\nint d, t, newnum, turn;\nnewnum = turn = 0; t=1;\nwhile (n>=t) t *= 10;\nt /=10;\nwhile (t>0) {\nd = n/t;\nn = n%t;\nt /= 10;\nif (turn) newnum = 10*newnum + d;\nturn = (turn + 1) % 2;\n}\nreturn newnum;\n}\nint main () {\nprintf (\"%d\", gate(14362));\nreturn 0;\n}\nThe value printed by the given C program is _______ . (Answer in integer)\n\nComputer Science and Information Technology (CS1)\nOrganising Institute: IIT Roorkee",
