    "id": "gate-2025-cs2-q52",
    "question": "Let Σ = {a, b, c}. For x ∈ Σ∗, and 𝛼 ∈ Σ, let #𝛼(x) denote the number of\noccurrences of 𝛼 in x.\nWhich one or more of the following option(s) define(s) regular language(s)?",
