        "id": "D",
        "text": "{w | w ∈ {a, b}∗, #a(w) ≡ 2 (mod 7), and #a(w) = #b(w)}\n\nComputer Science and Information Technology (CS2)\nOrganising Institute: IIT Roorkee"
